SELECT analytics_order_facts.channel, SUM(analytics_order_facts.gross_revenue) AS gross_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 8 AND analytics_order_facts.region = 'South' AND analytics_order_facts.customer_segment = 'enterprise' GROUP BY analytics_order_facts.channel ORDER BY gross_revenue DESC, analytics_order_facts.channel ASC LIMIT 5
